sys_variable_value.value:
(function execute(inputs, outputs) {
    var helper = new x_1815796_itsmgr_0.AiBotHelper();
    
    var response = helper._generateRequest(
        inputs.prompt, 
        inputs.model, 
        inputs.file_ids
    );

    if (response.startsWith('Error:')) {
        outputs.success = false;
        outputs.error_message = response;
        outputs.answer = "";
    } else {
        outputs.success = true;
        outputs.answer = response;
        outputs.error_message = "";
    }

})(inputs, outputs);

